gvH(){return"\u042d\u0442\u043e \u0441\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u0430\u044f \u0437\u0430\u043c\u0435\u0442\u043a\u0430, \u0430 \u043d\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u0438\u0435. \u041e\u043d\u0430 \u043b\u0438\u0448\u044c \u043d\u0430\u043f\u043e\u043c\u0438\u043d\u0430\u0435\u0442, \u0447\u0442\u043e \u0438\u043d\u043e\u0433\u0434\u0430 \u043f\u043e\u043b\u0435\u0437\u043d\u0430 \u043a\u043e\u0440\u043e\u0442\u043a\u0430\u044f \u043d\u0435\u0434\u0435\u043b\u044f \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u043e\u0442\u0434\u044b\u0445\u0430. \u0415\u0441\u043b\u0438 \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u0435\u0442\u0435 \u0441\u0435\u0431\u044f \u0445\u043e\u0440\u043e\u0448\u043e \u2014 \u043c\u0435\u043d\u044f\u0442\u044c \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043d\u0443\u0436\u043d\u043e."},
